1	package stowage
2	
3	import (
4		"reflect"
5		"strings"
6		"testing"
7	)
8	
9	// 本文件为正式提交（Adjust）补充“不同目的地货物整舱互换”的回归保障。
10	//
11	// 已有满载互换的覆盖使用相同目的地；这里覆盖两个舱位分别装着不同目的地、
12	// 且货物全部不允许混装的情况。合法性按整次调整全部完成后的最终配载判断：
13	// 交换过程中若逐条移动会出现暂时超重（目的地货物尚未全部移出）与暂时的
14	// 不同目的地共舱，这些中间状态都不得导致拒绝；整体交换完成后两个舱位仍
15	// 各自只含同一目的地货物、总重量不变，必须成功。
16	//
17	// 同一场景下只互换一件货物时，最终两舱都同时含上海与北京货物，总重量并
18	// 未超限，但全部货物不允许混装，整次调整必须按 C1 的混装冲突拒绝，且四件
19	// 货物都留在原舱，不能先完成其中一次移动。
20	
21	// 初始配载：C1、C2 承重均为 100 千克；
22	// C1 装去上海的 G1（40）、G2（60），C2 装去北京的 G3（40）、G4（60），
23	// 四件货物均不允许混装。两舱都恰好满载。
24	func newCrossDestinationSwapRegistry(t *testing.T) *Registry {
25		t.Helper()
26		r := NewRegistry()
27		mustRegisterCompartment(t, r, "C1", 100)
28		mustRegisterCompartment(t, r, "C2", 100)
29		mustRegisterCargo(t, r, "G1", 40, "上海", false)
30		mustRegisterCargo(t, r, "G2", 60, "上海", false)
31		mustRegisterCargo(t, r, "G3", 40, "北京", false)
32		mustRegisterCargo(t, r, "G4", 60, "北京", false)
33		mustAdjust(t, r, "init", []Op{
34			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
35			{Kind: OpLoad, CargoID: "G2", Target: "C1"},
36			{Kind: OpLoad, CargoID: "G3", Target: "C2"},
37			{Kind: OpLoad, CargoID: "G4", Target: "C2"},
38		})
39		return r
40	}
41	
42	// swapOpPermutations 返回整舱互换四条移动操作的全部 24 种先后次序，
43	// 用于保护“操作在清单中的先后次序不影响能否成功、最终配载与变化记录”。
44	func swapOpPermutations() [][]Op {
45		base := []Op{
46			{Kind: OpMove, CargoID: "G1", Target: "C2"},
47			{Kind: OpMove, CargoID: "G2", Target: "C2"},
48			{Kind: OpMove, CargoID: "G3", Target: "C1"},
49			{Kind: OpMove, CargoID: "G4", Target: "C1"},
50		}
51		var out [][]Op
52		var perm func(int)
53		perm = func(start int) {
54			if start == len(base) {
55				out = append(out, append([]Op(nil), base...))
56				return
57			}
58			for i := start; i < len(base); i++ {
59				base[start], base[i] = base[i], base[start]
60				perm(start + 1)
61				base[start], base[i] = base[i], base[start]
62			}
63		}
64		perm(0)
65		return out
66	}
67	
68	// 不同目的地、全部不允许混装的两舱整舱互换应成功。交换若按逐条移动执行，
69	// 中间会出现暂时超重（如先把 G1、G2 移入仍装着 G3、G4 的 C2：200 > 100）
70	// 与暂时的不同目的地共舱；这些中间状态都不能导致拒绝。该保障对四条移动
71	// 的全部先后次序成立。
72	func TestAdjustCrossDestinationFullCabinSwapSucceeds(t *testing.T) {
73		for i, ops := range swapOpPermutations() {
74			t.Run("次序", func(t *testing.T) {
75				r := newCrossDestinationSwapRegistry(t)
76	
77				res, err := r.Adjust("swap-full", ops)
78				if err != nil {
79					t.Fatalf("第 %d 种次序：整舱互换按最终配载应合法，却被拒绝: %v", i, err)
80				}
81				if res == nil || res.ID != "swap-full" {
82					t.Fatalf("第 %d 种次序：成功结果异常: %+v", i, res)
83				}
84	
85				// 货物变化保留四件货物各自的原舱位与新舱位，按货物编号排列。
86				wantCargoChanges := []CargoChange{
87					{CargoID: "G1", From: "C1", To: "C2"},
88					{CargoID: "G2", From: "C1", To: "C2"},
89					{CargoID: "G3", From: "C2", To: "C1"},
90					{CargoID: "G4", From: "C2", To: "C1"},
91				}
92				if !reflect.DeepEqual(res.CargoChanges, wantCargoChanges) {
93					t.Fatalf("第 %d 种次序：货物变化错误: got=%+v want=%+v",
94						i, res.CargoChanges, wantCargoChanges)
95				}
96	
97				// 两个舱位都应有 100 -> 100 的重量变化记录，按舱位编号排列；
98				// 不能因前后重量相等就省略。
99				wantCompChanges := []CompartmentChange{
100					{CompartmentID: "C1", WeightBefore: 100, WeightAfter: 100},
101					{CompartmentID: "C2", WeightBefore: 100, WeightAfter: 100},
102				}
103				if !reflect.DeepEqual(res.CompartmentChanges, wantCompChanges) {
104					t.Fatalf("第 %d 种次序：舱位重量变化错误: got=%+v want=%+v",
105						i, res.CompartmentChanges, wantCompChanges)
106				}
107	
108				// 最终配载：C1 只含 G3、G4（北京），C2 只含 G1、G2（上海），
109				// 两舱已用 100、剩余 0。
110				c1, _ := r.Compartment("C1")
111				if c1.UsedWeight != 100 || c1.RemainingWeight != 0 ||
112					!reflect.DeepEqual(cargoIDs(*c1), []string{"G3", "G4"}) {
113					t.Fatalf("第 %d 种次序：C1 最终配载错误: %+v", i, c1)
114				}
115				c2, _ := r.Compartment("C2")
116				if c2.UsedWeight != 100 || c2.RemainingWeight != 0 ||
117					!reflect.DeepEqual(cargoIDs(*c2), []string{"G1", "G2"}) {
118					t.Fatalf("第 %d 种次序：C2 最终配载错误: %+v", i, c2)
119				}
120	
121				// 每件货物的归属与舱内清单一致；货物不能遗漏，也不能同时留在
122				// 原舱和目标舱。
123				wantAt := map[string]string{
124					"G1": "C2", "G2": "C2", "G3": "C1", "G4": "C1",
125				}
126				for id, wantComp := range wantAt {
127					cv, _ := r.Cargo(id)
128					if !cv.Loaded || cv.CompartmentID != wantComp {
129						t.Fatalf("第 %d 种次序：货物 %s 应在 %s，实际 %q（loaded=%v）",
130							i, id, wantComp, cv.CompartmentID, cv.Loaded)
131					}
132				}
133	
134				// 重量、目的地和混装许可保持原值。
135				assertSwapCargoProfilesUnchanged(t, r)
136	
137				// 两舱清单与货物归属严格一一对应：每个舱位恰好两件，四件货物
138				// 各出现一次。
139				if len(c1.Cargo) != 2 || len(c2.Cargo) != 2 {
140					t.Fatalf("第 %d 种次序：交换后不应遗漏或重复货物: C1=%d 件 C2=%d 件",
141						i, len(c1.Cargo), len(c2.Cargo))
142				}
143			})
144		}
145	}
146	
147	// assertSwapCargoProfilesUnchanged 核对四件货物的重量、目的地与混装许可
148	// 始终保持登记原值，仅归属随调整改变。
149	func assertSwapCargoProfilesUnchanged(t *testing.T, r *Registry) {
150		t.Helper()
151		want := map[string]struct {
152			weight      int64
153			destination string
154		}{
155			"G1": {40, "上海"},
156			"G2": {60, "上海"},
157			"G3": {40, "北京"},
158			"G4": {60, "北京"},
159		}
160		for id, w := range want {
161			cv, _ := r.Cargo(id)
162			if cv.Weight != w.weight || cv.Destination != w.destination || cv.AllowMixed {
163				t.Fatalf("货物 %s 的登记资料被改变: %+v", id, cv)
164			}
165		}
166	}
167	
168	// 同一场景下只交换 G1 与 G3：最终 C1 含 G2（上海）、G3（北京），
169	// C2 含 G1（上海）、G4（北京），两舱总重量仍是 100，没有超重，但全部
170	// 货物不允许混装，整次调整必须失败，不返回成功结果。结构化错误报告
171	// 字典序最靠前的违规舱位 C1 的混装冲突，并指出其中编号最靠前的不允许
172	// 混装货物 G2，说明中能看出涉及 C1。
173	func TestAdjustCrossDestinationPartialSwapMixedConflictRejected(t *testing.T) {
174		// 两种先后次序都覆盖到：不能先完成其中一次移动再拒绝另一次。
175		for _, tc := range []struct {
176			name string
177			ops  []Op
178		}{
179			{name: "G1先行", ops: []Op{
180				{Kind: OpMove, CargoID: "G1", Target: "C2"},
181				{Kind: OpMove, CargoID: "G3", Target: "C1"},
182			}},
183			{name: "G3先行", ops: []Op{
184				{Kind: OpMove, CargoID: "G3", Target: "C1"},
185				{Kind: OpMove, CargoID: "G1", Target: "C2"},
186			}},
187		} {
188			t.Run(tc.name, func(t *testing.T) {
189				r := newCrossDestinationSwapRegistry(t)
190	
191				compBefore := snapshotCompartments(r, "C1", "C2")
192				cargoBefore := snapshotCargo(r, "G1", "G2", "G3", "G4")
193	
194				se := submitExpectReject(t, r, "swap-partial", tc.ops)
195				if se.Kind != ErrMixedLoading {
196					t.Fatalf("应按混装冲突拒绝，实际 Kind=%s", se.Kind)
197				}
198				// C1 最终含 G2（上海，禁混）与 G3（北京，禁混），违规货物为
199				// {G2, G3}，编号最靠前的是 G2（而不是移入的 G3）。
200				if se.ID != "G2" {
201					t.Fatalf("应指出 C1 内编号最靠前的不允许混装货物 G2，实际 ID=%q", se.ID)
202				}
203				if !strings.Contains(se.Error(), "C1") {
204					t.Fatalf("混装说明应指出冲突舱位 C1: %s", se.Error())
205				}
206				if se.AdjustmentID != "swap-partial" {
207					t.Fatalf("错误应携带调整编号 swap-partial，实际 %q", se.AdjustmentID)
208				}
209	
210				// 整次调整不生效：四件货物仍在各自原舱，不能先完成其中一次移动。
211				assertCompartmentsUnchanged(t, r, compBefore)
212				assertCargoUnchanged(t, r, cargoBefore)
213	
214				// 再明确核对两个舱位的完整清单、已用与剩余重量保持原样。
215				c1, _ := r.Compartment("C1")
216				if c1.UsedWeight != 100 || c1.RemainingWeight != 0 ||
217					!reflect.DeepEqual(cargoIDs(*c1), []string{"G1", "G2"}) {
218					t.Fatalf("拒绝后 C1 应仍为 G1、G2 且满载: %+v", c1)
219				}
220				c2, _ := r.Compartment("C2")
221				if c2.UsedWeight != 100 || c2.RemainingWeight != 0 ||
222					!reflect.DeepEqual(cargoIDs(*c2), []string{"G3", "G4"}) {
223					t.Fatalf("拒绝后 C2 应仍为 G3、G4 且满载: %+v", c2)
224				}
225				assertSwapCargoProfilesUnchanged(t, r)
226			})
227		}
228	}
