1	package stowage
2	
3	// 本文件集中维护装载、卸下、移动三种操作的货物去向规则，使预演安排
4	// （Preview）、正式生效（Adjust）与货物变化记录三处共用同一份去向判断，
5	// 避免某一处修改后其他结果不同步。
6	//
7	// 去向只有三条：装载从未装载到目标舱位；卸下从原舱位回到未装载；
8	// 移动从原舱位到目标舱位。未装载一律以空舱位编号表示。
9	
10	// cargoRoute 描述一件货物在一次调整中的去向：from 为原舱位、to 为
11	// 最终舱位，空字符串表示未装载。
12	type cargoRoute struct {
13		from string
14		to   string
15	}
16	
17	// routeFor 是三种操作唯一的去向规则。调用方必须已完成逐条校验：
18	// 装载与移动的 target 非 nil，货物当前状态与操作种类相符；卸下忽略
19	// 目标值，target 为 nil 且不参与去向。
20	//
21	// 预演的货物变化记录、模拟配载落点与正式生效都由这里得到 from/to，
22	// 因此同一批安排在预览与正式提交中逐件货物的原舱位、最终舱位一致。
23	func routeFor(kind OpKind, current string, target *compartment) cargoRoute {
24		switch kind {
25		case OpLoad:
26			return cargoRoute{from: "", to: target.id}
27		case OpUnload:
28			return cargoRoute{from: current, to: ""}
29		case OpMove:
30			return cargoRoute{from: current, to: target.id}
31		}
32		// 不可达：prepareOps 已拒绝无法识别的操作种类，routeFor 只会收到
33		// 装载、卸下、移动三种之一。
34		return cargoRoute{from: current, to: current}
35	}
36	
37	// relocate 按去向把一件货物从源舱位集合移到目标舱位集合，是模拟配载与
38	// 真实配载唯一的落点逻辑：from 非空时从源集合删除，to 非空时加入目标
39	// 集合。from/to 为空字符串表示该侧不涉及任何舱位（未装载），相应集合
40	// 传 nil 即为无操作。调用方持锁。
41	func relocate(c *cargo, rt cargoRoute, fromSet, toSet map[string]*cargo) {
42		if rt.from != "" {
43			delete(fromSet, c.id)
44		}
45		if rt.to != "" {
46			toSet[c.id] = c
47		}
48	}
49	
50	// touchedCompartments 按去向登记受影响舱位：装载只影响目标舱位，卸下
51	// 只影响原舱位，移动同时影响原舱位与目标舱位（交换中的两个舱位都会
52	// 纳入）。空舱位编号（未装载）不登记。
